    30	    public boolean canTransitionTo(Xgg74Status newStatus) {
    31	        return switch (this) {
    32	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
    33	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
    34	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
    35	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
    36	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
    37	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
    38	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
    39	        };
    40	    }
    41	}
